CREATE TABLE "SearchSession" ("id" TEXT NOT NULL PRIMARY KEY,"query" TEXT NOT NULL,"source" TEXT NOT NULL DEFAULT 'google',"pageUrl" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" DATETIME);
CREATE TABLE "SearchResult" ("id" TEXT NOT NULL PRIMARY KEY,"searchSessionId" TEXT NOT NULL,"title" TEXT NOT NULL,"url" TEXT NOT NULL,"normalizedUrl" TEXT NOT NULL,"domainId" TEXT NOT NULL,"position" INTEGER NOT NULL,"scanStatus" TEXT NOT NULL DEFAULT 'Queued',"httpStatus" INTEGER,"scanDuration" INTEGER,"error" TEXT,"scannedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SearchResult_searchSessionId_fkey" FOREIGN KEY ("searchSessionId") REFERENCES "SearchSession" ("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "SearchResult_domainId_fkey" FOREIGN KEY ("domainId") REFERENCES "Domain" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "DiscordLink" ("id" TEXT NOT NULL PRIMARY KEY,"searchResultId" TEXT NOT NULL,"url" TEXT NOT NULL,"inviteCode" TEXT NOT NULL,"sourcePage" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DiscordLink_searchResultId_fkey" FOREIGN KEY ("searchResultId") REFERENCES "SearchResult" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Domain" ("id" TEXT NOT NULL PRIMARY KEY,"hostname" TEXT NOT NULL,"firstSeen" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastSeen" DATETIME NOT NULL);
CREATE TABLE "HostingLocation" ("id" TEXT NOT NULL PRIMARY KEY,"domainId" TEXT NOT NULL,"ipAddress" TEXT NOT NULL,"country" TEXT,"countryCode" TEXT,"region" TEXT,"city" TEXT,"asn" TEXT,"provider" TEXT,"status" TEXT NOT NULL DEFAULT 'Completed',"checkedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "HostingLocation_domainId_fkey" FOREIGN KEY ("domainId") REFERENCES "Domain" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Lead" ("id" TEXT NOT NULL PRIMARY KEY,"domainId" TEXT NOT NULL,"searchResultId" TEXT,"status" TEXT NOT NULL DEFAULT 'New',"priority" TEXT NOT NULL DEFAULT 'Medium',"notes" TEXT NOT NULL DEFAULT '',"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "Lead_domainId_fkey" FOREIGN KEY ("domainId") REFERENCES "Domain" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "Lead_searchResultId_fkey" FOREIGN KEY ("searchResultId") REFERENCES "SearchResult" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "LeadActivity" ("id" TEXT NOT NULL PRIMARY KEY,"leadId" TEXT NOT NULL,"type" TEXT NOT NULL,"description" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "LeadActivity_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Setting" ("id" TEXT NOT NULL PRIMARY KEY,"value" TEXT NOT NULL,"updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "SearchResult_searchSessionId_normalizedUrl_key" ON "SearchResult"("searchSessionId", "normalizedUrl");
CREATE UNIQUE INDEX "DiscordLink_searchResultId_url_key" ON "DiscordLink"("searchResultId", "url");
CREATE UNIQUE INDEX "Domain_hostname_key" ON "Domain"("hostname");
CREATE UNIQUE INDEX "HostingLocation_domainId_key" ON "HostingLocation"("domainId");
CREATE UNIQUE INDEX "Lead_domainId_key" ON "Lead"("domainId");
